mapper.select:
select p.post_id, p.title, p.category, p.visibility, p.content, p.author_id, p.comment_count, p.view_count, p.create_time, p.update_time, ifnull(nullif(trim(u.real_name), ''), u.nick_name) as author_name, nullif(trim(mp.community_nickname), '') as author_community_nickname, u.member_department as author_department, u.avatar as author_avatar from qt_forum_post p left join sys_user u on p.author_id = u.user_id left join qt_member_profile mp on mp.user_id = u.user_id
and p.author_id = #{authorId} and p.category = #{category}
order by p.create_time desc, p.post_id desc

mapper.update:
update qt_forum_post
set title = #{title}, category = #{category}, visibility = #{visibility}, content = #{content}, update_time = now()
where post_id = #{postId}

update qt_forum_post p
set p.comment_count = (select count(*) from qt_forum_comment c where c.post_id = p.post_id)
where p.post_id = #{postId}

update qt_forum_post
set view_count = view_count + 1
where post_id = #{postId}
